void reach_pos(int32_t x,int32_t y){


	flag=0; // set 0 for x dir in TIM2 IRQ Handler
	x_pid_init();
	x_pid_set_target(x);
	systickDelayMs_polling(3000);
	tim2_10ms_interrupt_init();
	while(flag_x == 0);



	flag=1; // set 1 for x dir in TIM2 IRQ Handler
	y_pid_init();
	y_pid_set_target(y);
	systickDelayMs_polling(3000);
	tim2_10ms_interrupt_init();
	while(flag_y == 0);


}

int32_t to_mm(float meter){
	return (int32_t)(meter*1000);
}


void TIM2_IRQHandler(void){
	TIM2->SR &= ~(1<<0); // clear flag




	if(flag==0){
		x_pid_update(0.01f,&flag_x);
		data_arr_x[count_x++] = (int32_t)get_position_x_mm();
	}
	else{
		y_pid_update(0.01f,&flag_y);
		data_arr_y[count_y++] = (int32_t)get_position_y_mm();
	}


}


